// alertRetroMappings is the ADDITIVE, conflict-safe retro applied to EXISTING v11-alert-* indices
// on upgrade: it re-pins the embedded event bags (flat_object) that the full alertIndexMappings template
// covers for new indices. Existing alert indices already carry dynamically-inferred Side/top-level types
// (e.g. target.ip as text); retyping those would 400, so the retro only ADDS new/untyped fields and the
// full type-convergence happens on reindex/roll-off.

// alertRetroMappings is the ADDITIVE, conflict-safe retro applied to EXISTING v11-alert-*
// indices on upgrade: it re-pins the embedded event bags (flat_object) + the typed Side fields
// that the full alertIndexMappings template covers for new indices. It intentionally OMITS the
// utm.* pin: existing alert indices may already carry utm.* dynamically inferred as text, and
// pinning it keyword would 400 the upgrade. They keep their inferred types there and converge to
// the keyword pin on their next reindex/roll-off.
const alertRetroMappings = `{"lastEvent":{"type":"object","properties":{"event":{"type":"flat_object"},"controls":{"type":"keyword"}}},"events":{"type":"object","properties":{"event":{"type":"flat_object"},"controls":{"type":"keyword"}}}}`

func getOpenSearchContainerID() (string, error) {
	containerIDs, err := utils.RunCmdWithOutput("docker", "ps", "-q", "-f", "name=utmstack_node1")
	if err != nil {
		return "", fmt.Errorf("error getting opensearch container: %v", err)
	}
	if len(containerIDs) == 0 {
		return "", fmt.Errorf("opensearch container not found")
	}
	return containerIDs[0], nil
}

func execCurl(containerID string, method, url, data string) error {
	cnf := config.GetConfig()
	args := []string{"exec", containerID, "curl", "-s", "-k", "-u", "admin:" + cnf.OpenSearchPassword, "-X", method}
	if data != "" {
		args = append(args, "-H", "Content-Type: application/json", "-d", data)
	}
	args = append(args, url)

	_, err := utils.RunCmdWithOutput("docker", args...)
	return err
}

func InitOpenSearch() error {
	containerID, err := getOpenSearchContainerID()
	if err != nil {
		return err
	}

	// Wait for OpenSearch to be ready
	for intent := 0; intent <= 10; intent++ {
		time.Sleep(1 * time.Minute)

		err := execCurl(containerID, "GET", "https://localhost:9200/_cluster/health?wait_for_status=green&timeout=50s", "")
		if err != nil {
			if intent >= 10 {
				return err
			}
		} else {
			break
		}
	}

	// Create snapshot repository
	snapshotData := `{"type":"fs","settings":{"location":"/usr/share/opensearch/.utm_geoip/","compress":true}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_snapshot/.utm_geoip", snapshotData); err != nil {
		return err
	}

	// Create index template
	templateData := `{"index_patterns":["v11-alert-*","v11-log-*",".utm-*",".utmstack-*"],"template":{"settings":{"index.number_of_shards":1,"index.number_of_replicas":0,"index.mapping.total_fields.limit":50000}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_indexes", templateData); err != nil {
		return err
	}

	// v11 settings-only template (covers log + alert) — unchanged from v11.
	logTemplateData := `{"index_patterns":["v11-log-*","v11-alert-*"],"template":{"settings":{"index.max_shards":30000}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_log_indexes", logTemplateData); err != nil {
		return err
	}

	// Canonical log mapping template: scoped to v11-log-* ONLY (alert docs
	// carry severity as an integer — they must not inherit the log-side text
	// type). Pins EVERY standardized field so a field is never inferred
	// differently across log indices. Priority 10 so it composes with the
	// settings-only utmstack_indexes template (priority 0).
	eventMappingsData := `{"index_patterns":["v11-log-*"],"priority":10,"template":{"settings":{"index.mapping.total_fields.limit":50000},"mappings":{"dynamic":false,"properties":` + logIndexMappings + `}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_log_event_mappings", eventMappingsData); err != nil {
		return err
	}

	// Canonical alert mapping template: pins every standardized Alert field
	// (numeric severity/status/impact) + the embedded Event copies (lastEvent,
	// events[*]) with the same deterministic types as the log family, so a
	// field is typed identically in log and alert indices. The alert mapping
	// exceeds OpenSearch's 1000-field template-validation default, so it
	// carries the 50000 total_fields.limit in its own settings.
	alertMappingsData := `{"index_patterns":["v11-alert-*"],"priority":10,"template":{"settings":{"index.mapping.total_fields.limit":50000},"mappings":{"dynamic":false,"properties":` + alertIndexMappings + `}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_alert_event_mappings", alertMappingsData); err != nil {
		return err
	}


	// Restore geoip snapshot
	restoreData := `{"indices":".utm-geoip","include_global_state":false}`
	if err := execCurl(containerID, "POST", "https://localhost:9200/_snapshot/.utm_geoip/.utm_geoip/_restore", restoreData); err != nil {
		return err
	}

	return nil
}

func UpdateOpenSearch() error{

	containerID, err := getOpenSearchContainerID()
	if err != nil {
		return err
	}

	// (Re)create the v11 settings-only log template (covers log + alert).
	logTemplateData := `{"index_patterns":["v11-log-*","v11-alert-*"],"template":{"settings":{"index.max_shards":30000}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_log_indexes", logTemplateData); err != nil {
		return err
	}

	// (Re)create the canonical log mapping template (v11-log-* only), so
	// indices created during an upgrade get the full predefined schema.
	eventMappingsData := `{"index_patterns":["v11-log-*"],"priority":10,"template":{"settings":{"index.mapping.total_fields.limit":50000},"mappings":{"dynamic":false,"properties":` + logIndexMappings + `}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_log_event_mappings", eventMappingsData); err != nil {
		return err
	}

	// (Re)create the canonical alert mapping template (v11-alert-*).
	alertMappingsData := `{"index_patterns":["v11-alert-*"],"priority":10,"template":{"settings":{"index.mapping.total_fields.limit":50000},"mappings":{"dynamic":false,"properties":` + alertIndexMappings + `}}}`
	if err := execCurl(containerID, "PUT", "https://localhost:9200/_index_template/utmstack_alert_event_mappings", alertMappingsData); err != nil {
		return err
	}

	// Retro-map already-existing v11-log-* indices with the ADDITIVE,
	// conflict-safe subset (newBagMappings): the ip .keyword sub-field (fixes
	// the coordinate-map terms-agg) + the event/controls bags. The full
	// canonical logIndexMappings applies to NEW indices via the template; the
	// retro does not retype existing leaves (a base-type change 400s and needs
	// a reindex) — old indices converge on their next reindex/roll-off.
	if err := execCurl(containerID, "PUT", "https://localhost:9200/v11-log-*/_mapping?allow_no_indices=true",
		`{"properties":` + newBagMappings + `}`); err != nil {
		return err
	}

	// Retro-map already-existing v11-alert-* indices with alertRetroMappings
	// (the embedded event bags pinned flat_object — new/untyped fields only).
	if err := execCurl(containerID, "PUT", "https://localhost:9200/v11-alert-*/_mapping?allow_no_indices=true",
		`{"properties":` + alertRetroMappings + `}`); err != nil {
		return err
	}

	// updated already existing index (update case)
	if err := execCurl(containerID, "PUT", "https://localhost:9200/v11-log-*,v11-alert-*/_settings?allow_no_indices=true", `{"index.max_shards":30000}`); err != nil {
		return err
	}

	if err := execCurl(containerID, "PUT", "https://localhost:9200/v11-alert-*,v11-log-*,.utm-*,.utmstack-*/_settings?allow_no_indices=true", `{"index.mapping.total_fields.limit":50000}`); err != nil {
		return err
	}
	return nil

}

